00048 static constexpr int     PROB_BITS   = 15;   // Nominal number of bits to represent probabilities
00049 static constexpr int     PROB_BITS_0 = 10;   // Number of bits to represent 1st estimate
00050 static constexpr int     PROB_BITS_1 = 14;   // Number of bits to represent 2nd estimate
00051 static constexpr int     MASK_0      = ~(~0u << PROB_BITS_0) << (PROB_BITS - PROB_BITS_0);
00052 static constexpr int     MASK_1      = ~(~0u << PROB_BITS_1) << (PROB_BITS - PROB_BITS_1);
00053 static constexpr uint8_t DWS         = 8;   // 0x47 Default window sizes
00054 
00055 struct BinFracBits
00056 {
00057   uint32_t intBits[2];
00058 };
00059 
00060 
00061 enum BPMType
00062 {
00063   BPM_Undefined = 0,
00064   BPM_Std,
00065   BPM_NUM
00066 };
00067 
00068 class ProbModelTables
00069 {
00070 protected:
00071   static const BinFracBits m_binFracBits[256];
00072   static const uint8_t      m_RenormTable_32  [ 32];          // Std         MP   MPI
00073 };
00074 
00075 
00076 
00077 class BinProbModelBase : public ProbModelTables
00078 {
00079 public:
00080   BinProbModelBase () {}
00081   ~BinProbModelBase() {}
00082   static uint32_t estFracBitsEP ()                    { return  (       1 << SCALE_BITS ); }
00083   static uint32_t estFracBitsEP ( unsigned numBins )  { return  ( numBins << SCALE_BITS ); }
00084 };
00085 
00086 
00087 
00088 
00089 class BinProbModel_Std : public BinProbModelBase
00090 {
00091 public:
00092   BinProbModel_Std()
00093   {
00094     uint16_t half = 1 << (PROB_BITS - 1);
00095     m_state[0]    = half;
00096     m_state[1]    = half;
00097     m_rate        = DWS;
00098   }
00099   ~BinProbModel_Std ()                {}
00100 public:
00101   void            init              ( int qp, int initId );
00102   void update(unsigned bin)
00103   {
00104     int rate0 = m_rate >> 4;
00105     int rate1 = m_rate & 15;
00106 
00107     m_state[0] -= (m_state[0] >> rate0) & MASK_0;
00108     m_state[1] -= (m_state[1] >> rate1) & MASK_1;
00109     if (bin)
00110     {
00111       m_state[0] += (0x7fffu >> rate0) & MASK_0;
00112       m_state[1] += (0x7fffu >> rate1) & MASK_1;
00113     }
00114   }
00115   void setLog2WindowSize(uint8_t log2WindowSize)
00116   {
00117     int rate0 = 2 + ((log2WindowSize >> 2) & 3);
00118     int rate1 = 3 + rate0 + (log2WindowSize & 3);
00119     m_rate    = 16 * rate0 + rate1;
00120     CHECK(rate1 > 9, "Second window size is too large!");
00121   }
00122   void estFracBitsUpdate(unsigned bin, uint64_t &b)
00123   {
00124     b += estFracBits(bin);
00125     update(bin);
00126   }
00127   uint32_t        estFracBits(unsigned bin) const { return getFracBitsArray().intBits[bin]; }
00128   static uint32_t estFracBitsTrm(unsigned bin) { return (bin ? 0x3bfbb : 0x0010c); }
00129   BinFracBits     getFracBitsArray() const { return m_binFracBits[state()]; }
00130 public:
00131   uint8_t state() const { return (m_state[0] + m_state[1]) >> 8; }
00132   uint8_t mps() const { return state() >> 7; }
00133   uint8_t getLPS(unsigned range) const
00134   {
00135     uint16_t q = state();
00136     if (q & 0x80)
00137       q = q ^ 0xff;
00138     return ((q >> 2) * (range >> 5) >> 1) + 4;
00139   }
00140   static uint8_t  getRenormBitsLPS  ( unsigned LPS )                    { return    m_RenormTable_32  [LPS>>3]; }
00141   static uint8_t  getRenormBitsRange( unsigned range )                  { return    1; }
00142   uint16_t getState() const { return m_state[0] + m_state[1]; }
00143   void     setState(uint16_t pState)
00144   {
00145     m_state[0] = (pState >> 1) & MASK_0;
00146     m_state[1] = (pState >> 1) & MASK_1;
00147   }
00148 public:
00149   uint64_t estFracExcessBits(const BinProbModel_Std &r) const
00150   {
00151     int n = 2 * state() + 1;
00152     return ((512 - n) * r.estFracBits(0) + n * r.estFracBits(1) + 256) >> 9;
00153   }
00154 private:
00155   uint16_t m_state[2];
00156   uint8_t  m_rate;
00157 };
