00164 class CtxSet
00165 {
00166 public:
00167   CtxSet( uint16_t offset, uint16_t size ) : Offset( offset ), Size( size ) {}
00168   CtxSet( const CtxSet& ctxSet ) : Offset( ctxSet.Offset ), Size( ctxSet.Size ) {}
00169   CtxSet( std::initializer_list<CtxSet> ctxSets );
00170 public:
00171   uint16_t  operator()  ()  const
00172   {
00173     return Offset;
00174   }
00175   uint16_t  operator()  ( uint16_t inc )  const
00176   {
00177     CHECKD( inc >= Size, "Specified context increment (" << inc << ") exceed range of context set [0;" << Size - 1 << "]." );
00178     return Offset + inc;
00179   }
00180   bool operator== ( const CtxSet& ctxSet ) const
00181   {
00182     return ( Offset == ctxSet.Offset && Size == ctxSet.Size );
00183   }
00184   bool operator!= ( const CtxSet& ctxSet ) const
00185   {
00186     return ( Offset != ctxSet.Offset || Size != ctxSet.Size );
00187   }
00188 public:
00189   uint16_t  Offset;
00190   uint16_t  Size;
00191 };
