00297 template <class BinProbModel>
00298 class CtxStore : public FracBitsAccess
00299 {
00300 public:
00301   CtxStore();
00302   CtxStore( bool dummy );
00303   CtxStore( const CtxStore<BinProbModel>& ctxStore );
00304 public:
00305   void copyFrom   ( const CtxStore<BinProbModel>& src )                        { checkInit(); ::memcpy( m_Ctx,               src.m_Ctx,               sizeof( BinProbModel ) * ContextSetCfg::NumberOfContexts ); }
00306   void copyFrom   ( const CtxStore<BinProbModel>& src, const CtxSet& ctxSet )  { checkInit(); ::memcpy( m_Ctx+ctxSet.Offset, src.m_Ctx+ctxSet.Offset, sizeof( BinProbModel ) * ctxSet.Size ); }
00307   void init       ( int qp, int initId );
00308   void setWinSizes( const std::vector<uint8_t>&   log2WindowSizes );
00309   void loadPStates( const std::vector<uint16_t>&  probStates );
00310   void savePStates( std::vector<uint16_t>&        probStates )  const;
00311 
00312   const BinProbModel& operator[]      ( unsigned  ctxId  )  const { return m_Ctx[ctxId]; }
00313   BinProbModel&       operator[]      ( unsigned  ctxId  )        { return m_Ctx[ctxId]; }
00314   uint32_t            estFracBits     ( unsigned  bin,
00315                                         unsigned  ctxId  )  const { return m_Ctx[ctxId].estFracBits(bin); }
00316 
00317   BinFracBits         getFracBitsArray( unsigned  ctxId  )  const { return m_Ctx[ctxId].getFracBitsArray(); }
00318 
00319 private:
00320   inline void checkInit() { if( m_Ctx ) return; m_CtxBuffer.resize( ContextSetCfg::NumberOfContexts ); m_Ctx = m_CtxBuffer.data(); }
00321 private:
00322   std::vector<BinProbModel> m_CtxBuffer;
00323   BinProbModel*             m_Ctx;
00324 };
