00329 class SubCtx
00330 {
00331   friend class Ctx;
00332 public:
00333   SubCtx( const CtxSet& ctxSet, const Ctx& ctx ) : m_CtxSet( ctxSet          ), m_Ctx( ctx          ) {}
00334   SubCtx( const SubCtx& subCtx )                 : m_CtxSet( subCtx.m_CtxSet ), m_Ctx( subCtx.m_Ctx ) {}
00335   const SubCtx& operator= ( const SubCtx& ) = delete;
00336 private:
00337   const CtxSet  m_CtxSet;
00338   const Ctx&    m_Ctx;
