00342 
00343 class Ctx : public ContextSetCfg
00344 {
00345 public:
00346   Ctx();
00347   Ctx( const BinProbModel_Std*    dummy );
00348   Ctx( const Ctx&                 ctx   );
00349 
00350 public:
00351   const Ctx& operator= ( const Ctx& ctx )
00352   {
00353     m_BPMType = ctx.m_BPMType;
00354     switch( m_BPMType )
00355     {
00356     case BPM_Std:   m_CtxStore_Std  .copyFrom( ctx.m_CtxStore_Std   );  break;
00357     default:        break;
00358     }
00359     ::memcpy( m_GRAdaptStats, ctx.m_GRAdaptStats, sizeof( unsigned ) * RExt__GOLOMB_RICE_ADAPTATION_STATISTICS_SETS );
00360     return *this;
00361   }
00362 
00363   SubCtx operator= ( SubCtx&& subCtx )
00364   {
00365     m_BPMType = subCtx.m_Ctx.m_BPMType;
00366     switch( m_BPMType )
00367     {
00368     case BPM_Std:   m_CtxStore_Std  .copyFrom( subCtx.m_Ctx.m_CtxStore_Std,   subCtx.m_CtxSet );  break;
00369     default:        break;
00370     }
00371     return std::move(subCtx);
00372   }
00373 
00374   void  init ( int qp, int initId )
00375   {
00376     switch( m_BPMType )
00377     {
00378     case BPM_Std:   m_CtxStore_Std  .init( qp, initId );  break;
00379     default:        break;
00380     }
00381     for( std::size_t k = 0; k < RExt__GOLOMB_RICE_ADAPTATION_STATISTICS_SETS; k++ )
00382     {
00383       m_GRAdaptStats[k] = 0;
00384     }
00385   }
00386 
00387   void  loadPStates( const std::vector<uint16_t>& probStates )
00388   {
00389     switch( m_BPMType )
00390     {
00391     case BPM_Std:   m_CtxStore_Std  .loadPStates( probStates );  break;
00392     default:        break;
00393     }
00394   }
00395 
00396   void  savePStates( std::vector<uint16_t>& probStates ) const
00397   {
00398     switch( m_BPMType )
00399     {
00400     case BPM_Std:   m_CtxStore_Std  .savePStates( probStates );  break;
00401     default:        break;
00402     }
00403   }
00404 
00405   void  initCtxAndWinSize( unsigned ctxId, const Ctx& ctx, const uint8_t winSize )
00406   {
00407     switch( m_BPMType )
00408     {
00409     case BPM_Std:
00410       m_CtxStore_Std  [ctxId] = ctx.m_CtxStore_Std  [ctxId];
00411       m_CtxStore_Std  [ctxId] . setLog2WindowSize   (winSize);
00412       break;
00413     default:
00414       break;
00415     }
00416   }
00417 
00418   const unsigned&     getGRAdaptStats ( unsigned      id )      const { return m_GRAdaptStats[id]; }
00419   unsigned&           getGRAdaptStats ( unsigned      id )            { return m_GRAdaptStats[id]; }
00420 
00421 public:
00422   unsigned            getBPMType      ()                        const { return m_BPMType; }
00423   const Ctx&          getCtx          ()                        const { return *this; }
00424   Ctx&                getCtx          ()                              { return *this; }
00425 
00426   explicit operator   const CtxStore<BinProbModel_Std>  &()     const { return m_CtxStore_Std; }
00427   explicit operator         CtxStore<BinProbModel_Std>  &()           { return m_CtxStore_Std; }
00428 
00429   const FracBitsAccess&   getFracBitsAcess()  const
00430   {
00431     switch( m_BPMType )
00432     {
00433     case BPM_Std:   return m_CtxStore_Std;
00434     default:        THROW("BPMType out of range");
00435     }
00436   }
00437 
00438 private:
00439   BPMType                       m_BPMType;
00440   CtxStore<BinProbModel_Std>    m_CtxStore_Std;
00441 protected:
00442   unsigned                      m_GRAdaptStats[RExt__GOLOMB_RICE_ADAPTATION_STATISTICS_SETS];
00443 #if ENABLE_SPLIT_PARALLELISM
00444 
00445 public:
00446   int64_t cacheId;
00447   bool    cacheUsed;
00448 #endif
00449 };
00450 
