00453 typedef dynamic_cache<Ctx> CtxCache;
00454 
00455 class TempCtx
00456 {
00457   TempCtx( const TempCtx& ) = delete;
00458   const TempCtx& operator=( const TempCtx& ) = delete;
00459 public:
00460   TempCtx ( CtxCache* cache )                     : m_ctx( *cache->get() ), m_cache( cache ) {}
00461   TempCtx ( CtxCache* cache, const Ctx& ctx    )  : m_ctx( *cache->get() ), m_cache( cache ) { m_ctx = ctx; }
00462   TempCtx ( CtxCache* cache, SubCtx&&   subCtx )  : m_ctx( *cache->get() ), m_cache( cache ) { m_ctx = std::forward<SubCtx>(subCtx); }
00463   ~TempCtx()                                      { m_cache->cache( &m_ctx ); }
00464   const Ctx& operator=( const Ctx& ctx )          { return ( m_ctx = ctx ); }
00465   SubCtx     operator=( SubCtx&&   subCtx )       { return m_ctx = std::forward<SubCtx>( subCtx ); }
00466   operator const Ctx& ()           const          { return m_ctx; }
00467   operator       Ctx& ()                          { return m_ctx; }
00468 private:
00469   Ctx&      m_ctx;
00470   CtxCache* m_cache;
00471 };
